file.content:
"""Audit orchestrator (AUDITOR_SPEC sections 4, 7, 8, 9, 16).

idea -> Planner (frozen plan v0) -> Researcher (data tools) -> Mathematician (backtest, baselines, statistics)
-> coded checks + one Naysayer critique -> verdict rules -> template report (+ optional Reporter prose).
Every step writes its result to state.json before the next starts; --resume continues from the last finished
step and never re-plans. Every UI element is driven by the events appended to events.jsonl.
"""
import datetime as dt
import json
import time
from pathlib import Path

import numpy as np
import pandas as pd

from src.llm import LLMError

from . import agents, backtest, checks, report as report_mod, verdict as verdict_mod
from .data import build_features, coverage as coverage_of
from .eventlog import EventLog
from .plan import plan_hash, validate, what_tested
from .universe import ALL, GROUPS, MARKET, SMALL_GROUPS

LLM_BUDGET, NON_REPORTER_CAP = 8, 7
STEPS = ("plan", "data", "backtest", "critique", "verdict", "report")


class AuditError(Exception):
    pass


class BudgetExceeded(AuditError):
    pass


class State:
    def __init__(self, path, data):
        self.path, self.data = Path(path), data

    @classmethod
    def new(cls, path, audit_id, idea):
        return cls(path, {"audit_id": audit_id, "idea": idea, "created": _now(), "llm_calls": 0,
                          "cost": {"prompt_tokens": 0, "completion_tokens": 0, "usd": 0.0},
                          "recoveries": [], "injected_used": False, "steps": {}})

    @classmethod
    def load(cls, path):
        path = Path(path)
        if not path.is_file():
            raise AuditError("cannot resume: %s does not exist" % path)
        return cls(path, json.loads(path.read_text(encoding="utf-8")))

    def save(self):
        tmp = self.path.with_suffix(".tmp")
        tmp.write_text(json.dumps(self.data, indent=1, default=_json_default), encoding="utf-8")
        tmp.replace(self.path)

    def done(self, step):
        return self.data["steps"].get(step, {}).get("status") == "done"

    def result(self, step):
        return self.data["steps"][step]["result"]

    def finish(self, step, result):
        self.data["steps"][step] = {"status": "done", "result": result, "finished": _now()}
        self.save()


class Budget:
    """At most 8 llm() calls per audit; the 8th is reserved for the Reporter (section 8)."""

    def __init__(self, state):
        self.state = state

    def check(self, role):
        n = self.state.data["llm_calls"]
        if role != "reporter" and n >= NON_REPORTER_CAP:
            raise BudgetExceeded("LLM call cap: %d of %d non-Reporter calls used" % (n, NON_REPORTER_CAP))
        if n >= LLM_BUDGET:
            raise BudgetExceeded("LLM budget of %d calls exhausted" % LLM_BUDGET)

    def count(self):
        self.state.data["llm_calls"] += 1
        self.state.save()


def _now():
    return dt.datetime.now(dt.timezone.utc).isoformat(timespec="seconds").replace("+00:00", "Z")


def _json_default(v):
    if hasattr(v, "item"):
        return v.item()
    if hasattr(v, "isoformat"):
        return v.isoformat()
    return str(v)


def _clean(obj):
    """JSON round-trip so state and events hold plain Python values only; NaN and inf become null."""
    return _no_nan(json.loads(json.dumps(obj, default=_json_default)))


def _no_nan(v):
    if isinstance(v, float) and not np.isfinite(v):
        return None
    if isinstance(v, dict):
        return {k: _no_nan(x) for k, x in v.items()}
    if isinstance(v, list):
        return [_no_nan(x) for x in v]
    return v


class Audit:
    def __init__(self, idea, audit_id, llm, tracer, root, cache_dir, fetchers, fault, resume, provider):
        self.audit_id, self.llm, self.tracer = audit_id, llm, tracer
        self.root, self.cache_dir, self.fetchers = Path(root), Path(cache_dir), fetchers
        self.fault, self.provider = fault, provider
        self.dir = self.root / audit_id
        self.dir.mkdir(parents=True, exist_ok=True)
        state_path = self.dir / "state.json"
        if resume:
            self.state = State.load(state_path)
            self.log = EventLog.resume(self.dir / "events.jsonl", audit_id)
        else:
            if state_path.exists() or (self.dir / "events.jsonl").exists():
                raise AuditError("audit %r already exists: use --resume %s or a new --id" % (audit_id, audit_id))
            self.state = State.new(state_path, audit_id, idea)
            self.log = EventLog(self.dir / "events.jsonl", audit_id)
        self.idea = self.state.data["idea"]
        self.budget = Budget(self.state)
        self.step = "start"
        self.data = {}           # prices, market, features, iv, earnings (in memory only)
        tracer.on_span = self._on_span

    # ------------------------------------------------------------------ events from spans and recoveries
    def _on_span(self, rec):
        if rec.get("kind") != "llm":
            return
        agent = rec["name"]
        cost = self.state.data["cost"]
        cost["prompt_tokens"] += int(rec.get("prompt_tokens", 0))
        cost["completion_tokens"] += int(rec.get("completion_tokens", 0))
        cost["usd"] += float(rec.get("cost", 0.0))
        self.state.save()
        self.log.emit("llm_call", agent, {"model": rec.get("model"), "prompt_tokens": int(rec.get("prompt_tokens", 0)),
                                          "completion_tokens": int(rec.get("completion_tokens", 0)),
                                          "cost_usd": float(rec.get("cost", 0.0)),
                                          "latency_ms": int(1000 * float(rec.get("duration", 0.0)))})
        if int(rec.get("attempts", 1) or 1) > 1:
            self.recovered(agent, "empty or off-schema LLM reply from the %s" % agent, "retried the call once")

    def recovered(self, agent, failed, action):
        injected = self.fault is not None and not self.state.data.get("injected_used")
        if injected:
            self.state.data["injected_used"] = True
        entry = {"failed": failed, "action": action, "injected": injected}
        self.state.data["recoveries"].append(entry)
        self.state.save()
        self.log.emit("recovered", agent, entry)

    def call(self, role, fn, *args):
        self.budget.check(role)
        self.budget.count()
        return fn(self.llm, *args)

    def agent(self, name, step):
        """Context manager emitting agent_started / agent_finished with a summary set by the caller."""
        audit = self

        class _Ctx:
            def __enter__(self_):
                self_.t0, self_.summary = time.time(), None
                self_.span = audit.tracer.span("agent", name, agent=name, step=step, audit_id=audit.audit_id)
                self_.rec = self_.span.__enter__()
                audit.log.emit("agent_started", name, {"step": step})
                return self_

            def __exit__(self_, exc_type, exc, tb):
                summary = _clean(self_.summary) if self_.summary is not None else None
                self_.rec["output"] = summary
                audit.log.emit("agent_finished", name, {"step": step, "status": "error" if exc else "ok",
                                                        "duration_ms": int(1000 * (time.time() - self_.t0)),
                                                        "summary": summary})
                self_.span.__exit__(exc_type, exc, tb)
                return False

        return _Ctx()

    # ------------------------------------------------------------------------------------------- steps
    def run(self):
        with self.tracer.span("workflow", "audit", audit_id=self.audit_id, provider=self.provider):
            return self._run()

    def _run(self):
        if "started" not in self.state.data:
            self.log.emit("audit_started", None, {"idea": self.idea, "trace_id": getattr(self.tracer, "trace_id", None),
                                                  "llm_budget": LLM_BUDGET, "fault": self.fault, "provider": self.provider})
            self.state.data["started"] = _now()
            self.state.save()
        try:
            self.step = "plan"
            if not self.state.done("plan"):
                self.step_plan()
            plan = self.state.result("plan")["plan"]
            cannot = bool(plan.get("refused") or plan.get("invalid_twice") or plan.get("core_trigger_tested") is False)
            if not cannot:
                self.step = "data"
                self.step_data()
                self.step = "backtest"
                if not self.state.done("backtest"):
                    self.step_backtest()
                self.step = "critique"
                if not self.state.done("critique"):
                    self.step_critique()
            self.step = "verdict"
            if not self.state.done("verdict"):
                self.step_verdict(cannot)
            self.step = "report"
            if not self.state.done("report"):
                self.step_report()
        except checks.LeakageError as e:
            self.log.emit("error", None, {"step": self.step, "message": "leakage check failed: %s" % e})
            raise AuditError("leakage check failed: %s" % e) from e
        except Exception as e:
            self.log.emit("error", None, {"step": self.step, "message": "%s: %s" % (type(e).__name__, e)})
            raise
        v = self.state.result("verdict")
        return {"verdict": v, "report_path": str(self.dir / "report.md"), "events_path": str(self.dir / "events.jsonl"),
                "state": self.state.data}

    def step_plan(self):
        with self.agent("planner", "plan") as a:
            raw = self.call("planner", agents.run_planner, self.idea, None)
            raws = [raw]
            plan, err = validate(raw)
            errors = []
            if err:
                errors.append(err)
                raw2 = self.call("planner", agents.run_planner, self.idea, err)
                raws.append(raw2)
                plan, err2 = validate(raw2)
                if err2:
                    errors.append(err2)
                    plan = {"refused": False, "invalid_twice": True, "errors": errors}
            frozen = _clean(plan)
            result = {"plan": frozen, "hash": plan_hash(frozen), "raw_replies": _clean(raws), "errors": errors,
                      "what_tested": what_tested(frozen) if not frozen.get("invalid_twice") else "no valid plan"}
            a.summary = {"plan": frozen, "plan_hash": result["hash"], "what_tested": result["what_tested"]}
        self.state.finish("plan", result)

    def _tool(self, name, args, fn):
        self.log.emit("tool_called", "researcher", {"tool": name, "args": args})
        t0 = time.time()
        with self.tracer.span("tool", name, agent="researcher", step="data", audit_id=self.audit_id) as rec:
            rec["input"] = args
            try:
                out = fn()
            except Exception as e:
                self.log.emit("tool_result", "researcher", {"tool": name, "ok": False, "duration_ms": int(1000 * (time.time() - t0)),
                                                           "summary": "%s: %s" % (type(e).__name__, e)})
                raise
            rec["output"] = out[1]
        self.log.emit("tool_result", "researcher", {"tool": name, "ok": True, "duration_ms": int(1000 * (time.time() - t0)),
                                                   "summary": out[1]})
        return out[0]

    def step_data(self):
        plan = self.state.result("plan")["plan"]
        tickers = GROUPS[plan["universe_group"]]
        straddle = plan["family"].startswith("straddle")
        quiet = self.state.done("data")             # on resume: reload data without replaying the events
        emit = (lambda *a, **k: None) if quiet else self.log.emit
        ctx = self.agent("researcher", "data") if not quiet else None
        if ctx:
            ctx.__enter__()
        try:
            def tool(name, args, fn):
                return fn()[0] if quiet else self._tool(name, args, fn)

            def get_prices():
                prices, skipped = self.fetchers["prices"](tickers, self.cache_dir)
                return (prices, skipped), "%d tickers with prices, %d skipped" % (len([t for t in prices if t not in MARKET]), len(skipped))

            prices, skipped = tool("get_prices", {"group": plan["universe_group"], "tickers": len(tickers)}, get_prices)
            emit("data_progress", "researcher", {"what": "prices", "percent": 33})

            def get_earnings():
                e = self.fetchers["earnings"]([t for t in tickers if t in prices], self.cache_dir)
                return e, "earnings dates for %d tickers" % sum(1 for v in e.values() if v)

            earnings = tool("get_earnings_dates", {"tickers": len(tickers)}, get_earnings)
            emit("data_progress", "researcher", {"what": "earnings", "percent": 66})
            iv = None
            if straddle:
                def get_iv():
                    # One fetch for all 50 tickers: DoltHub is queried per date window, so the cost is the same
                    # whatever the group, and the cache then serves every later audit.
                    df = self.fetchers["iv"](ALL, self.cache_dir,
                                             on_recovered=lambda f, a: self.recovered("researcher", f, a),
                                             fault_first_timeout=(self.fault == "dolthub_timeout"))
                    df = df[df["ticker"].isin([t for t in tickers if t in prices])]
                    return df, "%d implied-vol rows" % len(df)

                iv = tool("get_implied_vol", {"tickers": len(tickers)}, get_iv)
            market = {m: prices[m] for m in MARKET if m in prices}
            universe = {t: df for t, df in prices.items() if t not in MARKET}

            def features():
                f = build_features(universe, market, iv, earnings)
                return f, "%d ticker-days with features" % len(f)

            feats = tool("build_features", {"tickers": len(universe)}, features)
            emit("data_progress", "researcher", {"what": "features", "percent": 100})
            cov = coverage_of(universe, skipped, iv, earnings)
            self.data.update(prices=universe, market=market, features=feats, iv=iv, earnings=earnings, coverage=cov)
            if ctx:
                ctx.summary = {"coverage": {"tickers": len(universe), "skipped": skipped,
                                            "iv_rows": cov["iv_rows"], "tickers_without_earnings": cov["tickers_without_earnings"]}}
        except Exception:
            if ctx:
                ctx.__exit__(*__import__("sys").exc_info())
            raise
        if ctx:
            ctx.__exit__(None, None, None)
        if not quiet:
            self.state.finish("data", {"coverage": _clean(cov)})

    def step_backtest(self):
        plan = self.state.result("plan")["plan"]
        d = self.data
        prices, feats, earnings = d["prices"], d["features"], d["earnings"]
        calendar = d["market"]["SPY"].index
        with self.agent("mathematician", "backtest") as a:
            base, drops, trades = {}, {}, {}
            for split in ("train", "validation"):
                t, dr = backtest.run_backtest(prices, feats, plan, earnings, split)
                trades[split], drops[split] = t, dr
                base[split] = checks.stats(t, calendar)
            setups_val = backtest.select_setups(feats, plan, "validation")
            checks.assert_no_leakage(setups_val["date"])
            for t in trades.values():
                checks.assert_no_leakage(t["entry_date"])
            dates_max = max([setups_val["date"].max()] + [t["entry_date"].max() for t in trades.values() if len(t)]) if len(setups_val) else None

            no_cond = dict(plan, conditions={})
            bl_trades = {s: backtest.run_backtest(prices, feats, no_cond, earnings, s)[0] for s in ("train", "validation")}
            baseline = {s: checks.stats(bl_trades[s], calendar) for s in bl_trades}
            baseline["paired_ci_low"] = checks.paired_lower_bound(trades["validation"]["entry_date"], trades["validation"]["ret"],
                                                                  bl_trades["validation"]["entry_date"], bl_trades["validation"]["ret"], calendar)
            rate = len(trades["validation"]) / len(bl_trades["validation"]) if len(bl_trades["validation"]) else 0.0
            rng = np.random.default_rng(0)
            rand = {s: checks.stats(bl_trades[s][rng.random(len(bl_trades[s])) < rate], calendar) for s in bl_trades}

            stricter = None
            if plan["family"].startswith("straddle"):
                st = {s: backtest.run_backtest(prices, feats, plan, earnings, s, stricter=True)[0] for s in ("train", "validation")}
                stricter = {s: checks.stats(st[s], calendar) for s in st}
            all_trades = pd.concat([trades["train"], trades["validation"]], ignore_index=True)
            tail = checks.tail_risk(all_trades, plan["family"], float(trades["validation"]["ret"].sum()), calendar)

            payload = {"run": "base", "train": base["train"], "validation": base["validation"],
                       "baseline": dict(baseline["validation"], paired_ci_low=baseline["paired_ci_low"]),
                       "equity_train": checks.equity_curve(trades["train"]),
                       "equity_validation": checks.equity_curve(trades["validation"]),
                       "histogram": checks.histogram(all_trades["ret"])}
            self.log.emit("backtest_result", "mathematician", _clean(payload))
            if stricter:
                self.log.emit("backtest_result", "mathematician", _clean({
                    "run": "stricter_cost", "train": stricter["train"], "validation": stricter["validation"],
                    "baseline": payload["baseline"], "equity_train": [], "equity_validation": [], "histogram": {}}))
            result = {"base": base, "baseline": baseline, "random_baseline": rand, "stricter": stricter, "tail": tail,
                      "drops": drops, "dates_max": dates_max.date().isoformat() if dates_max is not None else None,
                      "n_trades": {s: int(len(t)) for s, t in trades.items()}}
            a.summary = {"validation_n": base["validation"]["n"], "validation_mean": base["validation"]["mean"]}
        self.state.finish("backtest", _clean(result))

    def _results(self):
        plan_r = self.state.result("plan")
        r = {"plan": plan_r["plan"], "what_tested": plan_r["what_tested"], "coverage": self.state.result("data")["coverage"]
             if self.state.done("data") else {}}
        r.update(self.state.result("backtest"))
        r["followup_downgrades"] = []
        if self.state.done("critique"):
            r["checks"] = self.state.result("critique")["checks"]
        return r

    def step_critique(self):
        results = self._results()
        window_count = report_mod.registry_count(self.root / "registry.jsonl")
        coded = checks.coded_checks(results, window_count)
        with self.agent("naysayer", "critique") as a:
            for c in coded:
                self.log.emit("check_result", "naysayer", _clean(c))
            results["checks"] = coded
            budget_hit, critique, doubts = False, "", []
            try:
                out = self.call("naysayer", agents.run_naysayer, agents.naysayer_context(results))
                critique, doubts = out["critique"], out["doubts"]
            except BudgetExceeded as e:
                budget_hit, critique = True, "LLM call cap hit before the critique: %s" % e
            except LLMError as e:
                critique = "Naysayer call failed: %s" % e
            a.summary = {"doubts": doubts, "critique": critique}
        self.state.finish("critique", {"checks": _clean(coded), "critique": critique, "doubts": doubts,
                                       "budget_hit": budget_hit, "window_count": window_count})

    def step_verdict(self, cannot):
        if cannot:
            results = {"plan": self.state.result("plan")["plan"]}
        else:
            results = self._results()
        v = verdict_mod.decide(results)
        self.log.emit("verdict", None, _clean(v))
        self.state.finish("verdict", _clean(v))

    def step_report(self):
        plan_r, v = self.state.result("plan"), self.state.result("verdict")
        plan = plan_r["plan"]
        bt = self.state.result("backtest") if self.state.done("backtest") else {}
        cr = self.state.result("critique") if self.state.done("critique") else {}
        cost = self.state.data["cost"]
        group = plan.get("universe_group")
        ctx = {"idea": self.idea, "audit_id": self.audit_id, "plan": plan, "plan_hash": plan_r["hash"],
               "what_tested": plan_r["what_tested"], "verdict": v,
               "coverage": self.state.result("data")["coverage"] if self.state.done("data") else {},
               "drops": bt.get("drops", {}), "base": bt.get("base", {}), "baseline": bt.get("baseline", {}),
               "random_baseline": bt.get("random_baseline", {}), "stricter": bt.get("stricter"), "tail": bt.get("tail", {}),
               "checks": cr.get("checks", []), "followups": [], "window_count": cr.get("window_count", 0),
               "critique": cr.get("critique"), "prose": None, "recoveries": self.state.data["recoveries"],
               "cost": {"calls": self.state.data["llm_calls"], "prompt_tokens": cost["prompt_tokens"],
                        "completion_tokens": cost["completion_tokens"], "usd": cost["usd"]},
               "trace_id": getattr(self.tracer, "trace_id", None),
               "small_group_note": ("%s has %d tickers: usually inconclusive for lack of trades" % (group, len(GROUPS[group]))
                                    if group in SMALL_GROUPS else None),
               "earnings_caveat": any(f.startswith("earnings") or f == "days_since_earnings" for f in (plan.get("conditions") or {})),
               "fake_llm": self.provider == "fake", "budget_hit": bool(cr.get("budget_hit")),
               "fault_note": ("Fault requested: %s, but no DoltHub fetch happens for %s, so nothing was injected."
                              % (self.fault, plan.get("family"))
                              if self.fault == "dolthub_timeout" and not str(plan.get("family", "")).startswith("straddle")
                              and not self.state.data["recoveries"] else None)}
        with self.agent("reporter", "report") as a:
            prose = None
            if not plan.get("refused"):
                try:
                    text = self.call("reporter", agents.run_reporter, report_mod.render(ctx))
                    prose = text if report_mod.prose_ok(text) else None
                except (LLMError, BudgetExceeded):
                    prose = None
            ctx["cost"]["calls"] = self.state.data["llm_calls"]
            ctx["cost"].update({k: cost[k] for k in ("prompt_tokens", "completion_tokens", "usd")})
            ctx["prose"] = prose
            path = self.dir / "report.md"
            path.write_text(report_mod.render(ctx), encoding="utf-8")
            report_mod.append_registry(self.root / "registry.jsonl", {
                "date": _now()[:10], "audit_id": self.audit_id, "idea": self.idea, "family": plan.get("family"),
                "universe_group": group, "plan_hash": plan_r["hash"], "verdict": v["verdict"], "provider": self.provider})
            self.log.emit("report_ready", "reporter", {"path": str(path), "trace_id": getattr(self.tracer, "trace_id", None),
                                                      "prose_included": prose is not None})
            a.summary = {"prose_included": prose is not None}
        self.state.finish("report", {"path": str(path), "prose_included": prose is not None})


def run_audit(idea, audit_id, llm, tracer, *, root, cache_dir, fetchers, fault=None, resume=False, provider="deepseek"):
    """Run (or resume) one audit. Returns {"verdict", "report_path", "events_path", "state"}."""
    return Audit(idea, audit_id, llm, tracer, root, cache_dir, fetchers, fault, resume, provider).run()

"""Verdict rules (AUDITOR_SPEC section 7), in code. LLMs explain but cannot override."""

MIN_N, MIN_BLOCKS = 30, 6
CORE_REASON = "core of the idea not testable with available data"


def decide(results):
    """-> {"verdict", "reason", "headline", "downgrades"} from the orchestrator's results dict."""
    plan = results["plan"]
    if plan.get("refused"):
        return _out("cannot_audit", "refused")
    if plan.get("invalid_twice"):
        return _out("cannot_audit", "no valid plan")
    if plan.get("core_trigger_tested") is False:
        return _out("cannot_audit", CORE_REASON)

    val, train = results["base"]["validation"], results["base"]["train"]
    baseline = results["baseline"]
    headline = {"n": val["n"], "mean": val["mean"], "ci_low": val["ci_low"], "paired_ci_low": baseline.get("paired_ci_low")}
    if val["n"] < MIN_N:
        return _out("inconclusive", "not enough evidence: validation n < %d" % MIN_N, headline)
    if val["blocks"] < MIN_BLOCKS:
        return _out("inconclusive", "not enough evidence: trades fall in fewer than %d distinct 10-trading-day blocks" % MIN_BLOCKS, headline)
    if val["mean"] <= 0:
        return _out("kill", "validation mean <= 0 with enough evidence", headline)

    failed = []
    if not val["ci_low"] > 0:
        failed.append("lower bound of the validation mean is not above 0")
    paired = baseline.get("paired_ci_low")
    if paired is None or not paired > 0:
        failed.append("paired lower bound against the no-condition baseline is not above 0")
    if not train["mean"] > baseline["train"]["mean"]:
        failed.append("train mean is not above the train baseline mean")
    if plan["family"].startswith("straddle"):
        stricter = results.get("stricter") or {}
        s_val = stricter.get("validation") if stricter else None
        if not (s_val and s_val.get("ci_low", 0) > 0):
            failed.append("fails the stricter-cost check")
    if failed:
        return _out("inconclusive", "positive but not convincing: " + "; ".join(failed), headline)

    downgrades = []
    if results.get("tail", {}).get("fails"):
        downgrades.append({"cause": "tail risk", "from": "promising", "to": "inconclusive"})
    for d in results.get("followup_downgrades") or []:
        downgrades.append({"cause": d["cause"], "from": "promising", "to": "inconclusive"})
    if downgrades:
        return _out("inconclusive", "promising on the base rules, downgraded: " + "; ".join(d["cause"] for d in downgrades), headline, downgrades)
    return _out("promising", "all rules passed", headline)


def _out(verdict, reason, headline=None, downgrades=None):
    return {"verdict": verdict, "reason": reason, "headline": headline or {}, "downgrades": downgrades or []}

"""Statistics and coded checks (AUDITOR_SPEC section 7).

bootstrap_mean: block bootstrap over 10-trading-day blocks of entry dates, 2000 resamples, reporting the 2.5th
and 97.5th percentiles of the mean. paired_lower_bound resamples the same blocks for two trade sets.
"""
import numpy as np
import pandas as pd

BLOCK_DAYS = 10
N_BOOT = 2000
VALIDATION_END = pd.Timestamp("2026-06-30")
MIN_N, MIN_BLOCKS = 30, 6
FIVE_PCT_LINE = ("About 5% of plans with no real edge pass this test by chance; testing many variants of one "
                 "idea raises that.")


class LeakageError(AssertionError):
    pass


def assert_no_leakage(dates, cutoff=VALIDATION_END):
    """Raise LeakageError if any setup/feature date is after the validation window."""
    dates = pd.to_datetime(pd.Series(dates))
    if len(dates) and dates.max() > cutoff:
        raise LeakageError("date %s is after the cutoff %s" % (dates.max().date(), cutoff.date()))


def _positions(dates, calendar):
    return np.asarray(calendar.searchsorted(pd.DatetimeIndex(dates)), dtype=int)


def block_ids(dates, calendar):
    return _positions(dates, calendar) // BLOCK_DAYS


def _block_sums(dates, returns, calendar, block_index):
    """Per-block (sum, count) arrays aligned to block_index (a dict block id -> position)."""
    sums, counts = np.zeros(len(block_index)), np.zeros(len(block_index))
    for b, r in zip(block_ids(dates, calendar), np.asarray(returns, dtype=float)):
        sums[block_index[b]] += r
        counts[block_index[b]] += 1
    return sums, counts


def bootstrap_mean(dates, returns, calendar, n_boot=N_BOOT, seed=0):
    """(2.5th, 97.5th percentile) of the mean under a block bootstrap. (nan, nan) with no trades."""
    returns = np.asarray(returns, dtype=float)
    if len(returns) == 0:
        return (float("nan"), float("nan"))
    blocks = sorted(set(block_ids(dates, calendar)))
    if len(blocks) < 2:
        m = float(returns.mean())
        return (m, m)
    index = {b: i for i, b in enumerate(blocks)}
    sums, counts = _block_sums(dates, returns, calendar, index)
    rng = np.random.default_rng(seed)
    picks = rng.integers(0, len(blocks), size=(n_boot, len(blocks)))
    means = sums[picks].sum(axis=1) / counts[picks].sum(axis=1)
    return (float(np.percentile(means, 2.5)), float(np.percentile(means, 97.5)))


def paired_lower_bound(dates_a, ret_a, dates_b, ret_b, calendar, n_boot=N_BOOT, seed=0):
    """2.5th percentile of (mean_a - mean_b) over the same resampled blocks (the union of both block sets)."""
    ret_a, ret_b = np.asarray(ret_a, dtype=float), np.asarray(ret_b, dtype=float)
    if len(ret_a) == 0 or len(ret_b) == 0:
        return float("nan")
    blocks = sorted(set(block_ids(dates_a, calendar)) | set(block_ids(dates_b, calendar)))
    index = {b: i for i, b in enumerate(blocks)}
    sa, ca = _block_sums(dates_a, ret_a, calendar, index)
    sb, cb = _block_sums(dates_b, ret_b, calendar, index)
    if len(blocks) < 2:
        return float(ret_a.mean() - ret_b.mean())
    rng = np.random.default_rng(seed)
    picks = rng.integers(0, len(blocks), size=(n_boot, len(blocks)))
    with np.errstate(invalid="ignore", divide="ignore"):
        diff = sa[picks].sum(axis=1) / ca[picks].sum(axis=1) - sb[picks].sum(axis=1) / cb[picks].sum(axis=1)
    diff = diff[np.isfinite(diff)]
    return float(np.percentile(diff, 2.5)) if len(diff) else float("nan")


def worst_window(trades, calendar):
    """Worst sum of trade returns over any 10-trading-day window of entry dates (0 with no trades)."""
    if len(trades) == 0:
        return 0.0
    pos = _positions(trades["entry_date"], calendar)
    daily = np.zeros(pos.max() + BLOCK_DAYS + 1)
    np.add.at(daily, pos, trades["ret"].to_numpy(float))
    rolling = np.convolve(daily, np.ones(BLOCK_DAYS), mode="valid")
    return float(min(rolling.min(), 0.0))


def stats(trades, calendar):
    if len(trades) == 0:
        return {"n": 0, "blocks": 0, "win_rate": 0.0, "mean": 0.0, "median": 0.0, "ci_low": 0.0, "ci_high": 0.0,
                "worst_trade": 0.0, "worst_window": 0.0}
    r = trades["ret"].to_numpy(float)
    lo, hi = bootstrap_mean(trades["entry_date"], r, calendar)
    return {"n": int(len(r)), "blocks": int(len(set(block_ids(trades["entry_date"], calendar)))),
            "win_rate": float((r > 0).mean()), "mean": float(r.mean()), "median": float(np.median(r)),
            "ci_low": lo, "ci_high": hi, "worst_trade": float(r.min()), "worst_window": worst_window(trades, calendar)}


def equity_curve(trades, max_points=300):
    """[[entry date iso, cumulative return], ...] by entry date, downsampled evenly to at most max_points."""
    if len(trades) == 0:
        return []
    t = trades.sort_values("entry_date")
    cum = t["ret"].to_numpy(float).cumsum()
    dates = [d.date().isoformat() for d in pd.DatetimeIndex(t["entry_date"])]
    idx = np.unique(np.linspace(0, len(cum) - 1, min(max_points, len(cum))).round().astype(int))
    return [[dates[i], float(cum[i])] for i in idx]


def histogram(returns, bins=20):
    r = np.asarray(returns, dtype=float)
    r = r[np.isfinite(r)]
    if len(r) == 0:
        return {"edges": [], "counts": []}
    p1, p99 = np.percentile(r, 1), np.percentile(r, 99)
    if p99 <= p1:
        p99 = p1 + 1e-9
    edges = np.linspace(p1, p99, bins + 1)
    inner, _ = np.histogram(r[(r >= p1) & (r <= p99)], bins=edges)
    counts = [int((r < p1).sum())] + [int(c) for c in inner] + [int((r > p99).sum())]
    return {"edges": [float(e) for e in edges], "counts": counts}


def tail_risk(all_trades, family, validation_total_gain, calendar=None):
    """Worst trade and worst 10-day window on train plus validation; the straddle_sell downgrade rule."""
    calendar = calendar if calendar is not None else pd.DatetimeIndex(sorted(set(pd.DatetimeIndex(all_trades["entry_date"])))) if len(all_trades) else pd.DatetimeIndex([])
    if len(all_trades) == 0:
        return {"worst_trade": 0.0, "worst_window": 0.0, "fails": False}
    r = all_trades["ret"].to_numpy(float)
    out = {"worst_trade": float(r.min()), "worst_window": worst_window(all_trades, calendar), "fails": False}
    if family == "straddle_sell":
        premium = all_trades["premium"].to_numpy(float)
        avg = float(premium.mean()) if len(premium) else 0.0
        loss_pct = r * premium                        # return x premium share = % of stock price
        out["worst_trade_pct"] = float(loss_pct.min())
        out["worst_trade_premiums"] = float((loss_pct / avg).min()) if avg else float(r.min())
        out["worst_window_vs_gain"] = {"worst_window": out["worst_window"], "validation_total_gain": float(validation_total_gain)}
        out["fails"] = bool(out["worst_trade_premiums"] < -5 or -out["worst_window"] > validation_total_gain)
    return out


def coded_checks(results, registry_count):
    """The 7 always-run Naysayer checks as {check, passed, value, note}."""
    plan = results["plan"]
    val, train = results["base"]["validation"], results["base"]["train"]
    out = []
    out.append({"check": "evidence", "passed": bool(val["n"] >= MIN_N and val["blocks"] >= MIN_BLOCKS),
                "value": {"n": val["n"], "blocks": val["blocks"]},
                "note": "validation needs n >= %d and at least %d distinct 10-trading-day blocks" % (MIN_N, MIN_BLOCKS)})
    dates_max = results.get("dates_max")
    out.append({"check": "leakage", "passed": True, "value": str(pd.Timestamp(dates_max).date()) if dates_max is not None else None,
                "note": "no feature or trade date after %s (earnings features exempt, see caveat)" % VALIDATION_END.date()})
    decay_ok = bool(val["mean"] > 0 and val["mean"] >= 0.5 * train["mean"])
    out.append({"check": "decay", "passed": decay_ok, "value": {"train_mean": train["mean"], "validation_mean": val["mean"]},
                "note": "validation mean %+.2f%% vs train mean %+.2f%%" % (100 * val["mean"], 100 * train["mean"])})
    out.append({"check": "shared_window", "passed": True, "value": int(registry_count),
                "note": "%d earlier audit(s) used this validation window. %s" % (registry_count, FIVE_PCT_LINE)})
    if plan["family"].startswith("straddle"):
        drops = results.get("drops", {}).get("validation", {})
        share = drops.get("earnings_in_window", 0) / val["n"] if val["n"] else 0.0
        stricter = results.get("stricter") or {}
        s_val = stricter.get("validation") if stricter else None
        passed = bool(s_val and s_val.get("ci_low", 0) > 0)
        out.append({"check": "cost_realism", "passed": passed,
                    "value": {"earnings_share": share, "stricter_ci_low": s_val.get("ci_low") if s_val else None},
                    "note": "%.0f%% of validation trades had earnings in the window (priced x1.20); stricter-cost lower bound %s"
                            % (100 * share, "%+.2f%%" % (100 * s_val["ci_low"]) if s_val else "n/a")})
    else:
        out.append({"check": "cost_realism", "passed": True, "value": None, "note": "stock_long: no fees or slippage modeled"})
    tail = results.get("tail") or {}
    out.append({"check": "tail_risk", "passed": not tail.get("fails", False),
                "value": {k: v for k, v in tail.items() if k != "fails"},
                "note": "worst trade %+.2f%%, worst 10-day window %+.2f%% (train plus validation)"
                        % (100 * tail.get("worst_trade", 0), 100 * tail.get("worst_window", 0))})
    out.append({"check": "data_drops", "passed": True, "value": results.get("drops", {}),
                "note": "setups dropped for exits past the cutoff or the data, stale implied vol, missing earnings coverage"})
    return out

"""Backtest (AUDITOR_SPEC section 2 trade rules, section 3 splits).

stock_long: entry at the setup day's Adj Close; stop and target are absolute prices; Open/High/Low are
scaled to the Adj Close scale; a gap through the stop or target fills at the Open; otherwise the first-hit
rule with the stop first on a same-day double hit; no hit by the horizon exits at that day's Adj Close.
Straddles: hold 10 days, payoff on split-adjusted Close, cost from the ATM formula with the section 2
haircuts. One open trade per ticker; a new entry only after the previous trade has closed.
"""
import numpy as np
import pandas as pd

from src.tools import matches

TRAIN = ("2015-01-01", "2025-12-31")
STRADDLE_TRAIN_START = "2020-01-01"
VALID = ("2026-01-01", "2026-06-30")
CUTOFF = pd.Timestamp("2026-01-01")        # a train trade must exit before this
HOLD = 10
COST_K, BUY_HAIRCUT, EARNINGS_FACTOR, SELL_HAIRCUT = 0.7979, 1.05, 1.20, 0.95
STRICTER_BUY, STRICTER_SELL = 1.10, 0.90
TRADE_COLUMNS = ["ticker", "entry_date", "exit_date", "entry", "exit", "ret"]


def split_window(family, split):
    if split == "validation":
        return pd.Timestamp(VALID[0]), pd.Timestamp(VALID[1])
    if split == "train":
        start = STRADDLE_TRAIN_START if family.startswith("straddle") else TRAIN[0]
        return pd.Timestamp(start), pd.Timestamp(TRAIN[1])
    raise ValueError("unknown split %r (the test split is never constructed)" % split)


def select_setups(features, plan, split):
    """Rows in the split's window whose features satisfy the plan's conditions (NaN never matches)."""
    start, end = split_window(plan["family"], split)
    f = features[(features["date"] >= start) & (features["date"] <= end)]
    conds = plan["conditions"]
    if conds:
        f = f.dropna(subset=list(conds))
        f = f[matches(f, conds)]
    return f.sort_values(["ticker", "date"])


def _positions(df, dates):
    return df.index.get_indexer(pd.DatetimeIndex(dates))


def stock_long_trades(prices, features, plan, split, stricter=False):
    e = plan["exit"]
    horizon, target_pct, stop_pct = int(e["horizon_days"]), float(e["target_pct"]), float(e["stop_pct"])
    setups = select_setups(features, plan, split)
    rows, drops = [], {"exit_after_cutoff": 0, "exit_past_data": 0}
    for ticker, grp in setups.groupby("ticker", sort=True):
        df = prices[ticker]
        adj = df["Adj Close"].to_numpy(float)
        factor = adj / df["Close"].to_numpy(float)
        op, hi, lo = (df[c].to_numpy(float) * factor for c in ("Open", "High", "Low"))
        dates, n = df.index, len(df)
        open_until = -1
        for pos in _positions(df, grp["date"]):
            if pos < 0 or pos <= open_until:
                continue
            entry = adj[pos]
            stop, target = entry * (1 - stop_pct), entry * (1 + target_pct)
            exit_price = exit_pos = None
            for i in range(pos + 1, min(pos + horizon, n - 1) + 1):
                if op[i] <= stop or op[i] >= target:
                    exit_price, exit_pos = op[i], i
                elif lo[i] <= stop:
                    exit_price, exit_pos = stop, i
                elif hi[i] >= target:
                    exit_price, exit_pos = target, i
                if exit_pos is not None:
                    break
            if exit_pos is None:
                if pos + horizon >= n:
                    drops["exit_past_data"] += 1
                    continue
                exit_price, exit_pos = adj[pos + horizon], pos + horizon
            if split == "train" and dates[exit_pos] >= CUTOFF:
                drops["exit_after_cutoff"] += 1
                continue
            open_until = exit_pos
            rows.append({"ticker": ticker, "entry_date": dates[pos], "exit_date": dates[exit_pos],
                         "entry": float(entry), "exit": float(exit_price), "ret": float(exit_price / entry - 1)})
    return pd.DataFrame(rows, columns=TRADE_COLUMNS), drops


def straddle_trades(prices, features, plan, split, earnings, stricter=False):
    buyer = plan["family"] == "straddle_buy"
    setups = select_setups(features, plan, split)
    rows = []
    drops = {"exit_after_cutoff": 0, "exit_past_data": 0, "stale_iv": 0, "earnings_in_window": 0}
    for ticker, grp in setups.groupby("ticker", sort=True):
        df = prices[ticker]
        close = df["Close"].to_numpy(float)
        dates, n = df.index, len(df)
        earn_pos = set(int(p) for p in df.index.searchsorted(pd.DatetimeIndex(earnings.get(ticker) or [])))
        open_until = -1
        for pos, iv in zip(_positions(df, grp["date"]), grp["iv"].to_numpy(float)):
            if pos < 0 or pos <= open_until:
                continue
            if not np.isfinite(iv):
                drops["stale_iv"] += 1
                continue
            if pos + HOLD >= n:
                drops["exit_past_data"] += 1
                continue
            exit_pos = pos + HOLD
            if split == "train" and dates[exit_pos] >= CUTOFF:
                drops["exit_after_cutoff"] += 1
                continue
            open_until = exit_pos
            formula = COST_K * iv * np.sqrt(HOLD / 252)
            payoff = abs(close[exit_pos] / close[pos] - 1)
            has_earnings = any(pos < ep <= exit_pos for ep in earn_pos)
            row = {"ticker": ticker, "entry_date": dates[pos], "exit_date": dates[exit_pos],
                   "entry": float(close[pos]), "exit": float(close[exit_pos])}
            if buyer:
                cost = formula * BUY_HAIRCUT * (EARNINGS_FACTOR if has_earnings else 1.0) * (STRICTER_BUY if stricter else 1.0)
                drops["earnings_in_window"] += int(has_earnings)
                row.update(cost=float(cost), ret=float(payoff / cost - 1))
            else:
                premium = formula * SELL_HAIRCUT * (STRICTER_SELL if stricter else 1.0)
                drops["earnings_in_window"] += int(has_earnings)
                row.update(premium=float(premium), ret=float((premium - payoff) / premium))
            rows.append(row)
    cols = TRADE_COLUMNS + (["cost"] if buyer else ["premium"])
    return pd.DataFrame(rows, columns=cols), drops


def run_backtest(prices, features, plan, earnings, split, stricter=False):
    """-> (trades, drops) for the plan's family on one split."""
    if plan["family"] == "stock_long":
        return stock_long_trades(prices, features, plan, split, stricter)
    return straddle_trades(prices, features, plan, split, earnings, stricter)

"""Report template (AUDITOR_SPEC section 9). Code writes every number, the verdict, caveats and the
disclaimer; the Reporter's prose is optional and checked against a banned-phrase list."""
import json
from pathlib import Path

from .checks import FIVE_PCT_LINE
from .plan import canonical
from .universe import GROUPS

BANNED = ("will profit", "guaranteed", "risk-free", "we recommend", "you should buy", "you should sell", "sure thing")
SUBTITLES = {"promising": "Passed a 6-month historical screen. Not a forecast. Not financial advice.",
             "inconclusive": "inconclusive: a strategy with no real edge lands here about half the time"}
LABELS = {"kill": "KILLED", "inconclusive": "INCONCLUSIVE", "promising": "PROMISING", "cannot_audit": "CANNOT AUDIT"}
EARNINGS_CAVEAT = ("Earnings caveat: actual report dates are used; companies usually announce dates weeks ahead, "
                   "so the look-ahead is small but not zero.")
FOOTER = ("Not financial advice. Survivorship bias: the universe is today's large caps. One validation window "
          "(2026-01-01 to 2026-06-30) shared by every audit. Costs are approximated (no fees for stocks; "
          "straddle costs from an ATM formula with haircuts). No position sizing is given.")


def prose_ok(text):
    low = (text or "").lower()
    return not any(b in low for b in BANNED)


def pct(x):
    return "n/a" if x is None else "%+.2f%%" % (100 * x)


def _stats_row(label, s):
    if not s:
        return "| %s | – | – | – | – | – | – | – |" % label
    return "| %s | %d | %d | %.0f%% | %s | %s | [%s, %s] | %s / %s |" % (
        label, s["n"], s["blocks"], 100 * s["win_rate"], pct(s["mean"]), pct(s["median"]), pct(s["ci_low"]), pct(s["ci_high"]),
        pct(s["worst_trade"]), pct(s["worst_window"]))


def render(ctx):
    v = ctx["verdict"]
    plan = ctx["plan"]
    label = LABELS.get(v["verdict"], v["verdict"].upper())
    lines = ["# Strategy Auditor report: %s" % label, "", ctx["what_tested"], "",
             "## 1. What was tested and the verdict", "",
             "**Verdict: %s.** %s" % (label, v["reason"])]
    if v["verdict"] in SUBTITLES:
        lines.append("")
        lines.append("*%s*" % SUBTITLES[v["verdict"]])
    if ctx.get("small_group_note"):
        lines += ["", "Note: %s." % ctx["small_group_note"]]
    if ctx.get("fake_llm"):
        lines += ["", "**FAKE LLM run (development only): the plan and critique were produced by keyword rules, not a model.**"]
    if ctx.get("budget_hit"):
        lines += ["", "The LLM call cap (7 calls for the Planner and Naysayer) was hit; the verdict rests on the evidence gathered so far."]
    if ctx.get("fault_note"):
        lines += ["", ctx["fault_note"]]
    h = v.get("headline") or {}
    if h:
        lines += ["", "Headline: validation n = %s, mean per trade %s, lower bound %s, paired lower bound vs baseline %s."
                  % (h.get("n", "–"), pct(h.get("mean")), pct(h.get("ci_low")), pct(h.get("paired_ci_low")))]

    lines += ["", "## 2. Idea, plan v0, assumptions", "", "Idea: %s" % ctx["idea"], "",
              "Plan v0 (frozen before any backtest), SHA-256 `%s`:" % ctx["plan_hash"], "", "```json",
              json.dumps(plan, indent=2, sort_keys=True), "```", ""]
    if plan.get("refused"):
        lines.append("Refused: %s" % plan.get("reason", ""))
    else:
        lines.append("Assumptions: " + ("; ".join(plan.get("assumptions") or []) or "none stated") + ".")
        lines.append("Not tested: " + ("; ".join(plan.get("not_tested") or []) or "nothing") + ".")
        if plan.get("universe_group") in GROUPS:
            lines.append("Universe: %s = %s." % (plan["universe_group"], ", ".join(GROUPS[plan["universe_group"]])))

    cov, drops = ctx.get("coverage") or {}, ctx.get("drops") or {}
    lines += ["", "## 3. Data coverage", ""]
    if cov:
        rows = cov.get("rows_per_ticker_year") or {}
        if rows:
            years = sorted({y for r in rows.values() for y in r})
            lines += ["| Ticker | " + " | ".join(years) + " |", "|---|" + "---|" * len(years)]
            lines += ["| %s | %s |" % (t, " | ".join(str(r.get(y, 0)) for y in years)) for t, r in rows.items()]
            lines.append("")
        lines.append("Skipped tickers (under 200 rows): %s." % (", ".join(cov.get("skipped") or []) or "none"))
        if cov.get("iv_range"):
            lines.append("Implied vol rows: %d, %s to %s." % (cov["iv_rows"], *cov["iv_range"]))
        first = cov.get("earnings_first_date") or {}
        if first:
            lines.append("Earliest earnings date per ticker: " + ", ".join("%s %s" % kv for kv in sorted(first.items())) + ".")
        if cov.get("tickers_without_earnings"):
            lines.append("No earnings coverage: %s (NaN earnings features; left out of F1)." % ", ".join(cov["tickers_without_earnings"]))
    for split in ("train", "validation"):
        d = drops.get(split)
        if d:
            lines.append("Dropped %s setups: %s." % (split, ", ".join("%s %d" % kv for kv in d.items())))
    if ctx.get("earnings_caveat"):
        lines += ["", EARNINGS_CAVEAT]

    lines += ["", "## 4. Results", "",
              "| Run | n | blocks | win | mean | median | 95% interval | worst trade / 10-day window |",
              "|---|---|---|---|---|---|---|---|"]
    base, bl = ctx.get("base") or {}, ctx.get("baseline") or {}
    lines.append(_stats_row("v0 train", base.get("train")))
    lines.append(_stats_row("v0 validation", base.get("validation")))
    lines.append(_stats_row("no-condition baseline, train", bl.get("train")))
    lines.append(_stats_row("no-condition baseline, validation", bl.get("validation")))
    rb = ctx.get("random_baseline") or {}
    if rb:
        lines.append(_stats_row("random selection at the same rate, validation (reported only)", rb.get("validation")))
    if ctx.get("stricter"):
        lines.append(_stats_row("stricter cost (+10% buyer / -10% seller), validation", ctx["stricter"].get("validation")))
    lines += ["", "Paired lower bound (v0 minus baseline, validation, 2.5th percentile): %s." % pct(bl.get("paired_ci_low"))]
    tail = ctx.get("tail") or {}
    if tail:
        extra = ""
        if "worst_trade_premiums" in tail:
            extra = " Seller losses: worst trade %.1f average premiums (%s of stock price); worst window %s vs total validation gain %s." % (
                tail["worst_trade_premiums"], pct(tail.get("worst_trade_pct")), pct(tail["worst_window"]),
                pct((tail.get("worst_window_vs_gain") or {}).get("validation_total_gain")))
        lines.append("Tail risk (train plus validation): worst trade %s, worst 10-trading-day window %s.%s" % (
            pct(tail.get("worst_trade")), pct(tail.get("worst_window")), extra))

    lines += ["", "## 5. Coded checks and follow-ups", "", "| Check | Passed | Note |", "|---|---|---|"]
    lines += ["| %s | %s | %s |" % (c["check"], "yes" if c["passed"] else "no", c["note"]) for c in ctx.get("checks") or []]
    fus = ctx.get("followups") or []
    lines += ["", "Follow-ups: " + ("none run (M1)" if not fus else "")]
    for f in fus:
        lines.append("- %s: %s. Result: %s. %s" % (f["id"], f["reason"], f.get("result", "n/a"),
                                                 ("Downgrade: %s" % f["downgrade"]) if f.get("downgrade") else "No downgrade."))
    if v.get("downgrades"):
        lines += ["", "Downgrades: " + "; ".join(d["cause"] for d in v["downgrades"]) + "."]

    lines += ["", "## 6. Shared validation window", "",
              "%d audit(s) have used this validation window before this one. %s" % (ctx.get("window_count", 0), FIVE_PCT_LINE)]

    lines += ["", "## 7. Naysayer critique and Reporter prose", "", "Naysayer: %s" % (ctx.get("critique") or "n/a")]
    if ctx.get("prose"):
        lines += ["", "Reporter: %s" % ctx["prose"]]
    else:
        lines += ["", "Reporter prose: not included."]

    lines += ["", "## 8. Recoveries", ""]
    recs = ctx.get("recoveries") or []
    lines += ["- [%s] %s: %s" % ("INJECTED" if r.get("injected") else "REAL", r["failed"], r["action"]) for r in recs] or ["none"]

    cost = ctx.get("cost") or {}
    lines += ["", "## 9. Cost and trace", "",
              "LLM calls: %s (prompt tokens %s, completion tokens %s), cost $%.4f (upper bound). neatlogs trace: %s." % (
                  cost.get("calls", 0), cost.get("prompt_tokens", 0), cost.get("completion_tokens", 0), cost.get("usd", 0.0),
                  ctx.get("trace_id") or "none")]
    lines += ["", "## 10. Disclaimer", "", FOOTER, ""]
    return "\n".join(lines)


def append_registry(path, line):
    path = Path(path)
    path.parent.mkdir(parents=True, exist_ok=True)
    with path.open("a", encoding="utf-8") as f:
        f.write(json.dumps(line, sort_keys=True) + "\n")


def registry_count(path):
    """Finished audits that used the shared validation window; fake-LLM development runs do not count."""
    path = Path(path)
    if not path.is_file():
        return 0
    n = 0
    for line in path.read_text(encoding="utf-8").splitlines():
        if not line.strip():
            continue
        try:
            if json.loads(line).get("provider") != "fake":
                n += 1
        except ValueError:
            continue
    return n


